package com.bankpli.javabank.credit;
import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.stereotype.Service;
@Service public class CreditScoringService {private final Executor executor;private final RiskDecisionService decisions;private final TrendAnalyzer trends;public CreditScoringService(@Qualifier("bureauExecutor")Executor e,RiskDecisionService d,TrendAnalyzer t){executor=e;decisions=d;trends=t;}public record Result(int composite,int responses,CreditDecision decision,TrendAnalyzer.Trend trend){}public Result score(List<Supplier<Integer>> bureaus,Duration timeout,List<Integer>history){if(bureaus==null||bureaus.size()!=5)throw new IllegalArgumentException("Exactly five bureaus are required");BlockingQueue<Integer>q=new LinkedBlockingQueue<>();bureaus.forEach(b->CompletableFuture.supplyAsync(b,executor).thenAccept(q::offer).exceptionally(x->null));List<Integer>scores=new ArrayList<>();long deadline=System.nanoTime()+timeout.toNanos();while(scores.size()<3){long left=deadline-System.nanoTime();if(left<=0)break;try{Integer v=q.poll(left,TimeUnit.NANOSECONDS);if(v==null)break;scores.add(v);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}if(scores.size()<3)throw new IllegalStateException("Credit bureau quorum not reached");int composite=(int)Math.floor(scores.stream().mapToInt(Integer::intValue).average().orElse(0));return new Result(composite,scores.size(),decisions.decide(composite),trends.analyze(history));}}
